from pathlib import Path
import json

ROOT=Path(__file__).parent
BASE='''*{box-sizing:border-box}html{scroll-behavior:auto}body{margin:0;font-family:Arial,sans-serif;font-size:16px;line-height:1.5;color:var(--ink);background:var(--paper)}a{color:inherit;text-underline-offset:5px}button,input{font:inherit}button,.button{cursor:pointer;min-height:48px;padding:12px 22px;background:var(--ink);color:var(--paper);border:1px solid var(--ink);text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:20px}button:hover,.button:hover{filter:brightness(.88)}input{width:100%;min-height:50px;padding:12px;border:1px solid var(--line);background:transparent;color:inherit;border-radius:0}label{display:block;font-size:14px}label input{margin-top:8px}h1,h2,h3,p,figure{margin:0}h1,h2,h3{font-weight:400;line-height:1.08}p{max-width:64ch}img{display:block;max-width:100%}header,footer{padding:26px 4vw}header{display:flex;justify-content:space-between;align-items:center;gap:24px;border-bottom:1px solid var(--line)}nav{display:flex;gap:30px;align-items:center;font-size:14px}nav a{text-decoration:none}nav a:hover{text-decoration:underline}.brand{text-decoration:none;font-size:27px;letter-spacing:-1px}.wrap{padding:0 4vw}.small{font-size:13px}.muted{color:var(--muted)}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase}.rule{border-top:1px solid var(--line)}.section{padding:85px 0}.section-title{font-size:46px;letter-spacing:-1.7px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:6vw}.fields{display:grid;gap:20px}.status{min-height:28px;font-size:14px;padding-top:12px}.demo{font-size:12px;border-top:1px solid var(--line);padding-top:20px;margin-top:35px}.skip{position:absolute;left:10px;top:-100px;padding:10px;background:white;color:black;z-index:20}.skip:focus{top:10px}:focus-visible{outline:3px solid currentColor;outline-offset:5px}footer{border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:24px}button.secondary{background:transparent;color:var(--ink)}@media(max-width:700px){header,footer{padding:20px 6vw}.wrap{padding:0 6vw}header{align-items:flex-start;flex-wrap:wrap;gap:15px}nav{gap:20px;font-size:13px;flex-wrap:wrap}.brand{font-size:25px}.grid2{grid-template-columns:1fr;gap:35px}.section{padding:50px 0}.section-title{font-size:35px}footer{flex-direction:column}.eyebrow{font-size:11px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}'''

def page(id,title,css,body,js=''):
    path=ROOT/id;path.mkdir(exist_ok=True)
    (path/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{BASE}{css}</style></head><body><a class="skip" href="#main">Skip to content</a>{body}<script>{js}</script></body></html>',encoding='utf-8')

def fields(date=False):
    return '<label>Your name<input name="name" autocomplete="name" required></label><label>Email address<input name="email" type="email" autocomplete="email" required></label>'+('<label>Preferred date<input name="date" type="date" required></label>' if date else '')

formjs="document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();document.querySelector('[role=status]').textContent='Thank you. Your enquiry has been noted in this local demonstration only. No data has been sent.';});"

works=[('gallery-152229.jpg','Eugène Atget','Rue de la Montagne-Sainte-Geneviève','1898'),('gallery-325449.jpg','Alfred Stieglitz','The Steerage','1907'),('gallery-162340.jpg','Eugène Atget','Nymphéa','1922–23'),('gallery-152228.jpg','Eugène Atget','Versailles, Fountain of Triumphant France','1904')]
def work(w,i):
    return f'<figure class="work work-{i}"><div class="image-mat"><img src="../../../assets/intervals/{w[0]}" alt="{w[2]}, photograph by {w[1]}" loading="eager"></div><figcaption><span>{w[1]}</span><span>{w[2]}, {w[3]}</span><span class="credit">Cleveland Museum of Art · CC0</span></figcaption></figure>'
page('intervals','Intervals — Between the ordinary.', '''
:root{--ink:#111;--paper:#fff;--muted:#666;--line:#c9c9c9}body{font-family:Helvetica,Arial,sans-serif}.brand{font-size:32px;font-weight:600;letter-spacing:-1.8px}.intro{display:grid;grid-template-columns:1.4fr .6fr;gap:8vw;padding:62px 0 55px}.intro h1{font-size:clamp(48px,6.6vw,100px);letter-spacing:-.065em;line-height:.98}.intro-copy{align-self:end;font-size:17px;line-height:1.55}.intro-copy .eyebrow{margin-bottom:20px}.works{display:grid;grid-template-columns:1fr 1fr;gap:70px 6vw}.image-mat{background:#f3f3f3;height:580px;display:flex;align-items:center;justify-content:center;padding:38px}.image-mat img{width:100%;height:100%;object-fit:contain;filter:grayscale(1)}figcaption{padding-top:18px;font-size:13px;display:grid;grid-template-columns:1fr 1.3fr;gap:5px 20px}.credit{grid-column:2;color:#666;font-size:11px}.work-2{padding-top:110px}.work-3 .image-mat,.work-4 .image-mat{height:420px}.artists{margin-top:90px}.artists h2{font-size:45px}.artist{padding-top:25px;border-top:1px solid var(--line)}.artist h3{font-size:26px;margin-bottom:18px}.artist p{font-size:16px}.enquiry{margin-top:80px;padding:70px 0 80px;border-top:1px solid #111}.enquiry h2{font-size:54px;letter-spacing:-2px}.enquiry p{margin-top:20px;max-width:32ch}.enquiry form{max-width:520px}.footer-logo{font-size:38px;letter-spacing:-2px}@media(max-width:700px){.intro{grid-template-columns:1fr;padding:42px 0 38px;gap:28px}.intro h1{font-size:58px;max-width:8ch}.intro-copy{font-size:16px}.intro-copy .eyebrow{margin-bottom:14px}.works{grid-template-columns:1fr;gap:36px}.image-mat{height:430px;padding:22px}.work-2{padding-top:0}.work-3 .image-mat,.work-4 .image-mat{height:350px}.artists{margin-top:55px}.enquiry{margin-top:45px;padding:45px 0}.enquiry h2{font-size:42px}figcaption{grid-template-columns:1fr;gap:4px}.credit{grid-column:1}.artists h2{font-size:36px}}''',f'''
<header><a class="brand" href="#">Intervals</a><nav aria-label="Main"><a href="#works">Selected works</a><a href="#artists">The artists</a><a href="#enquiry">Enquire ↗</a></nav></header>
<main id="main" class="wrap"><section class="intro"><h1>Between<br>the ordinary.</h1><div class="intro-copy"><p class="eyebrow">A photographic conversation</p><p>A street before the city wakes. People held between departure and arrival. Light caught on the surface of water. Intervals brings photographs by Eugène Atget and Alfred Stieglitz into conversation.</p></div></section><section id="works" aria-label="Selected works" class="works">{''.join(work(w,i+1) for i,w in enumerate(works))}</section><section id="artists" class="section artists rule"><div class="grid2"><h2>Two ways<br>of looking.</h2><div class="fields"><article class="artist"><h3>Eugène Atget <span class="small muted">1857–1927</span></h3><p>Atget photographed the streets, architecture and gardens of Paris. His patient attention to the everyday created an enduring record of a changing city.</p></article><article class="artist"><h3>Alfred Stieglitz <span class="small muted">1864–1946</span></h3><p>A photographer and advocate for photography as an art form, Stieglitz explored modern life through carefully observed scenes and experimental compositions.</p></article></div></div></section><section id="enquiry" class="enquiry grid2"><div><h2>Continue the<br>conversation.</h2><p>For exhibition enquiries, leave your name and email.</p><p class="small muted">Local demonstration. This form does not send data.</p></div><form data-testid="enquiry-form" class="fields">{fields()}<button type="submit">Send an exhibition enquiry <span>↗</span></button><p data-testid="form-status" role="status" class="status"></p></form></section></main><footer><span class="footer-logo">Intervals</span><span class="small">Fictional client · Local demonstration<br>All photographs: Cleveland Museum of Art, CC0</span></footer>''',formjs)

