def row(n,q,s):return f'<tr data-batch data-status="{s}"><td class="product">{n}</td><td class="qty">{q}<span class="mobile-unit"> pieces</span></td><td><span class="badge {s}">{s.capitalize()}</span></td><td class="actions">'+(f'<button data-action type="button" aria-label="{("Start bake" if s=="queued" else "Mark ready")} {n}">{("Start bake" if s=="queued" else "Mark ready")} →</button>' if s!='ready' else '<span class="ready-check">✓ Complete</span>')+'</td></tr>'
page('hearth','Hearth — Today’s bake', '''
:root{--ink:#292b28;--paper:#f5f3ee;--muted:#686b63;--line:#d2d2c8}body{font-size:14px;font-variant-numeric:tabular-nums}header{padding:18px 3vw;background:#292b28;color:#f5f3ee;border:0}.brand{font:30px Georgia,serif;letter-spacing:-1px}.account{display:flex;gap:16px;align-items:center;font-size:12px}.avatar{border:1px solid #73766c;border-radius:50%;width:32px;height:32px;display:grid;place-items:center}.shell{padding:36px 3vw}.page-heading{display:flex;justify-content:space-between;gap:25px;align-items:center}.page-heading h1{font:44px Georgia,serif;letter-spacing:-1.5px}.page-heading p{font-size:13px;margin-top:10px;color:var(--muted)}.primary{background:#963d28;border-color:#963d28;color:#fff}.summary{display:grid;grid-template-columns:1.1fr 1fr 1fr 1fr;border:1px solid var(--line);margin:28px 0;background:#fbfaf6}.summary>div{padding:19px 24px;border-right:1px solid var(--line)}.summary>div:last-child{border:0}.summary strong{font-size:31px;line-height:1.2;font-weight:400;display:block;margin-top:8px}.summary small{font-size:12px;color:var(--muted)}.summary .total{border-top:3px solid #963d28;padding-top:16px}.workbench{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:28px}.panel{border:1px solid var(--line);background:#fbfaf6}.panel-head{padding:20px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.panel h2{font-size:18px;font-weight:500}.filters{display:flex;gap:5px;padding:17px 20px;border-bottom:1px solid var(--line)}.filters button{background:transparent;color:var(--muted);border:0;min-height:36px;font-size:13px;padding:7px 13px;border-radius:4px}.filters button[aria-pressed=true]{background:#292b28;color:#fff}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.06em;font-weight:400;color:var(--muted);padding:13px 20px;border-bottom:1px solid var(--line)}td{padding:20px;border-bottom:1px solid #e4e4db}.product{font-weight:500}.qty{text-align:right;font-size:20px}.qty-head{text-align:right}.badge{font-size:11px;padding:5px 9px;border-radius:3px;white-space:nowrap;background:#e7e8e1}.badge.baking{background:#f1dfc9;color:#704319}.badge.ready{background:#e1e9dd;color:#3c5935}.badge.queued{background:#e9e7e1;color:#625e54}.actions{text-align:right;white-space:nowrap}.actions button{min-height:34px;padding:7px 10px;background:none;color:#963d28;border:1px solid #c7ada4;border-radius:3px;font-size:11px}.ready-check{color:#586b50;font-size:11px}.mobile-unit{display:none}.table-foot{padding:17px 20px;color:var(--muted);font-size:12px}.side{display:grid;gap:20px;align-content:start}.oven{padding:20px 22px;border-bottom:1px solid var(--line)}.oven:last-child{border:0}.oven-top{display:flex;justify-content:space-between}.oven-temp{font-size:29px;line-height:1.2}.oven p{font-size:12px;margin-top:12px;color:var(--muted)}.oven progress{width:100%;height:5px;accent-color:#963d28;margin-top:14px}.stock-item{display:flex;justify-content:space-between;padding:16px 22px;border-bottom:1px solid #e4e4db}.stock-item:last-child{border:0}.stock-item strong{color:#963d28;font-weight:500}.collections{margin-top:23px}.collection-row{display:grid;grid-template-columns:80px 160px 1fr;gap:20px;padding:16px 22px;border-bottom:1px solid #e4e4db}.collection-row:last-child{border:0}.collection-row time{font-weight:500}.collection-row p{color:var(--muted);font-size:13px}.demo-bar{display:flex;justify-content:space-between;margin-top:28px;font-size:11px;color:var(--muted)}dialog{width:min(480px,calc(100vw - 32px));border:1px solid var(--line);padding:28px;background:var(--paper);color:var(--ink)}dialog::backdrop{background:#292b2870}dialog h2{font:32px Georgia,serif;margin-bottom:12px}dialog p{font-size:13px;margin-bottom:24px}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}dialog label+label{margin-top:18px}@media(max-width:1000px){.workbench{grid-template-columns:1fr}.side{grid-template-columns:1fr 1fr}td,th{padding-left:16px;padding-right:16px}}@media(max-width:700px){header{padding:16px 6vw}.account>span:first-child{display:none}.shell{padding:28px 6vw}.page-heading{align-items:flex-start}.page-heading h1{font-size:34px}.page-heading p{font-size:11px;max-width:23ch}.page-heading button{font-size:12px;padding:10px 13px;min-height:40px;white-space:nowrap}.summary{grid-template-columns:1fr 1fr;margin:24px 0}.summary>div{padding:15px 18px;border-bottom:1px solid var(--line)}.summary>div:nth-child(2){border-right:0}.summary .total{padding-top:12px}.summary>div:nth-child(3){border-bottom:0}.summary strong{font-size:28px}.summary small{font-size:11px}.workbench{gap:20px}.panel-head{padding:18px}.filters{padding:12px;gap:1px}.filters button{padding:8px 12px}thead{display:none}tbody{display:block;padding:0 17px}tr{display:grid;grid-template-columns:1fr auto;gap:11px;padding:19px 0;border-bottom:1px solid var(--line)}td{padding:0;border:0}.product{font-size:15px;align-self:center}.qty{font-size:18px}.mobile-unit{display:inline;font-size:10px;color:var(--muted)}.actions{align-self:center}.badge{display:inline-block}.actions button{font-size:11px;min-height:36px}.table-foot{font-size:11px;padding:14px 17px}.side{grid-template-columns:1fr}.collection-row{grid-template-columns:55px 1fr;gap:6px 15px;padding:16px 18px}.collection-row p{grid-column:2}.demo-bar{gap:20px;align-items:flex-start}.demo-bar span{max-width:23ch}}''',f'''
<header><a class="brand" href="#">hearth<span style="color:#bb725b">.</span></a><div class="account"><span>Canal Street</span><span>Alex Morgan · Shift lead</span><span class="avatar" aria-label="Demo account">AM</span></div></header><main id="main" class="shell"><div class="page-heading"><div><h1>Today’s bake.</h1><p>Wednesday 21 October · 09:12 <span aria-hidden="true">/</span> Canal Street</p></div><button type="button" class="primary" data-testid="add-batch">+ Add batch</button></div><section class="summary" aria-label="Bake summary"><div class="total"><small>Today’s planned pieces</small><strong id="total">248</strong></div><div><small>Ready for the counter</small><strong id="ready">144</strong></div><div><small>Currently baking</small><strong id="baking">48</strong></div><div><small>Waiting for an oven</small><strong id="queued">56</strong></div></section><div class="workbench"><div><section class="panel"><div class="panel-head"><h2>Production board</h2><span class="small muted" id="batch-count">5 batches</span></div><div class="filters" aria-label="Filter production"><button type="button" data-filter="all" aria-pressed="true">All</button><button type="button" data-filter="baking" aria-pressed="false">Baking</button><button type="button" data-filter="queued" aria-pressed="false">Queued</button><button type="button" data-filter="ready" aria-pressed="false">Ready</button></div><table><thead><tr><th scope="col">Product</th><th scope="col" class="qty-head">Pieces</th><th scope="col">Status</th><th scope="col" style="text-align:right">Next step</th></tr></thead><tbody>{''.join(row(*r) for r in rows)}</tbody></table><div class="table-foot" id="production-status" role="status">Local changes stay in this demonstration.</div></section><section class="panel collections"><div class="panel-head"><h2>Upcoming collections</h2><span class="small muted">3 orders</span></div><div class="collection-row"><time>09:30</time><strong>Jamie R.</strong><p>2 sourdough + 4 croissants</p></div><div class="collection-row"><time>10:00</time><strong>Studio North</strong><p>12 morning buns</p></div><div class="collection-row"><time>10:30</time><strong>Riley T.</strong><p>Focaccia + rye</p></div></section></div><aside class="side"><section class="panel"><div class="panel-head"><h2>Ovens</h2><span class="small muted">2 in use</span></div><div class="oven"><div class="oven-top"><strong>Oven 01</strong><span class="oven-temp">230°<span class="small">C</span></span></div><p>Country sourdough · 12 min left</p><progress max="100" value="65" aria-label="Oven 01 bake progress">65%</progress></div><div class="oven"><div class="oven-top"><strong>Oven 02</strong><span class="oven-temp">180°<span class="small">C</span></span></div><p>Holding temperature</p></div></section><section class="panel"><div class="panel-head"><h2>Stock to watch</h2><span style="color:#963d28">2 items</span></div><div class="stock-item"><span>Butter</span><strong>2.4 kg</strong></div><div class="stock-item"><span>Rye flour</span><strong>3 kg</strong></div></section></aside></div><div class="demo-bar"><span>Fictional client · Demo data · Local demonstration</span><span>Alex Morgan — demo account</span></div><dialog data-testid="batch-dialog" aria-labelledby="dialog-title"><h2 id="dialog-title">Add a batch</h2><p>Add a product to today’s queue. Changes are local to this demonstration.</p><form data-testid="batch-form"><label>Product<input name="product" required maxlength="100" autocomplete="off"></label><label>Quantity in pieces<input name="quantity" type="number" min="1" max="999999" step="1" required></label><div class="dialog-actions"><button type="button" class="secondary" id="cancel">Cancel</button><button type="submit" class="primary">Add batch</button></div></form></dialog></main>''','''
let filter='all';const body=document.querySelector('tbody'),dialog=document.querySelector('dialog');function update(){let totals={ready:0,baking:0,queued:0};const rows=[...body.querySelectorAll('[data-batch]')];rows.forEach(r=>{totals[r.dataset.status]+=Number(r.querySelector('.qty').firstChild.textContent);r.hidden=filter!=='all'&&r.dataset.status!==filter;r.style.display=r.hidden?'none':''});Object.keys(totals).forEach(k=>document.querySelector('#'+k).textContent=totals[k]);document.querySelector('#total').textContent=Object.values(totals).reduce((a,b)=>a+b,0);document.querySelector('#batch-count').textContent=rows.length+' batches';let shown=rows.filter(r=>!r.hidden).length;document.querySelector('#production-status').textContent=shown?shown+' batches shown · Changes are local to this demonstration.':'No batches in this state. Choose All to see the production board.';const u=new URL(location);u.searchParams.set('filter',filter);history.replaceState(null,'',u)}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));update()}));body.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let r=b.closest('[data-batch]');r.dataset.status=r.dataset.status==='queued'?'baking':'ready';let badge=r.querySelector('.badge');badge.className='badge '+r.dataset.status;badge.textContent=r.dataset.status==='baking'?'Baking':'Ready';if(r.dataset.status==='ready'){let s=document.createElement('span');s.className='ready-check';s.textContent='✓ Complete';b.replaceWith(s)}else{b.textContent='Mark ready →';b.setAttribute('aria-label','Mark ready '+r.querySelector('.product').textContent)}update()});document.querySelector('[data-testid=add-batch]').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel').addEventListener('click',()=>dialog.close());document.querySelector('[data-testid=batch-form]').addEventListener('submit',e=>{e.preventDefault();let data=new FormData(e.target),name=data.get('product').trim(),quantity=Number(data.get('quantity'));if(!name||!Number.isInteger(quantity)||quantity<1)return;let r=document.createElement('tr');r.setAttribute('data-batch','');r.dataset.status='queued';let p=document.createElement('td');p.className='product';p.textContent=name;let q=document.createElement('td');q.className='qty';q.append(document.createTextNode(quantity));let unit=document.createElement('span');unit.className='mobile-unit';unit.textContent=' pieces';q.append(unit);let st=document.createElement('td'),badge=document.createElement('span');badge.className='badge queued';badge.textContent='Queued';st.append(badge);let ac=document.createElement('td');ac.className='actions';let b=document.createElement('button');b.type='button';b.dataset.action='';b.textContent='Start bake →';b.setAttribute('aria-label','Start bake '+name);ac.append(b);r.append(p,q,st,ac);body.append(r);e.target.reset();dialog.close();filter='all';document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.filter==='all'));update()});const requested=new URL(location).searchParams.get('filter');if(['all','queued','baking','ready'].includes(requested)){filter=requested;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.filter===filter));update()}''')

